// Получаем массив транскриптов
const transcripts = $input.item.json.transcript;

// Функция для конвертации миллисекунд в формат времени
function msToTime(ms) {
  const totalSeconds = Math.floor(ms / 1000);
  const hours = Math.floor(totalSeconds / 3600);
  const minutes = Math.floor((totalSeconds % 3600) / 60);
  const seconds = totalSeconds % 60;
  const milliseconds = ms % 1000;

  return `${String(hours).padStart(2, '0')}:${String(minutes).padStart(2, '0')}:${String(seconds).padStart(2, '0')},${String(milliseconds).padStart(3, '0')}`;
}

// Формируем текст транскрипции
let formattedTranscript = '';

transcripts.forEach((item, index) => {
  const startTime = msToTime(item.startMs);
  const endTime = msToTime(item.endMs);

  formattedTranscript += `${startTime} --> ${endTime}\n`;
  formattedTranscript += `${item.text}\n\n`;
});

// Возвращаем результат
return {
  json: {
    formattedTranscript: formattedTranscript.trim()
  }
};
